def predict(board, action):
    row, col = action[1], action[2]
    action_char = action[0]

    # Find the cell at the given action coordinates
    cell = board[row][col]

    # Initialize the new board
    new_board = [list(row) for row in board]

    # Define the color change logic
    if action_char == 'MOUSE':
        if cell == 'R':
            new_board[row][col] = 'c'
            for r in range(max(0, row-1), min(63, row+2)):
                for c in range(max(0, col-1), min(63, col+2)):
                    if (r, c) != (row, col):
                        new_board[r][c] = 'c' if new_board[r][c] == 'R' else 'R'
        elif cell == 'c':
            new_board[row][col] = 'R'
            for r in range(max(0, row-1), min(63, row+2)):
                for c in range(max(0, col-1), min(63, col+2)):
                    if (r, c) != (row, col):
                        new_board[r][c] = 'R' if new_board[r][c] == 'c' else 'c'

    return [''.join(row) for row in new_board]
